// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testRegression_property() public {
        // Scenario: deploy with zero supply; initially owner = address(this)
        // Step 1: call owned() from a different account (alice) to set owner to alice (reference) or do nothing (bug)
        address alice = address(0xABCD);
        vm.prank(alice);
        c.owned();

        // Step 2: now call burn(0) as the original owner (address(this)). In reference, owner is still alice, so burn succeeds (alice is owner).
        // In buggy, owner was never changed (still address(this)), so burn also succeeds.
        // But after burn, we check owner: reference's owner = address(this) due to owned() call? Wait, reference owned() sets owner = msg.sender, so from alice it sets owner to alice. 
        // Actually reference owned() sets owner to msg.sender (alice), then burn() checks onlyOwner (owner == msg.sender). Here msg.sender for burn is address(this) which is NOT alice, so burn should revert in reference!
        // So the divergence: reference burn() reverts (since msg.sender != owner), buggy burn() succeeds (since owner was never changed and still equals msg.sender).
        // Let's adjust: initial owner is address(this). Alice calls owned() => reference sets owner to alice, bug does nothing. Then address(this) tries to burn(0). 
        // In reference: onlyOwner check fails (msg.sender != alice) => revert. In buggy: onlyOwner check passes (owner still address(this) == msg.sender) => burn succeeds.
        // So we check revert boolean.
        bool ok;
        try c.burn(0) {
            ok = true;
        } catch {
            ok = false;
        }
        // In reference, ok == false. In buggy, ok == true. So assertTrue(!ok) passes on reference, fails on buggy.
        assertTrue(!ok);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, "", ""); }
    function testRegression_property() public {
        address owner1 = address(1);
        address owner2 = address(2);
        vm.deal(owner1, 1 ether);
        vm.deal(owner2, 1 ether);

        // Set owner to owner1 via owned() from owner1
        vm.prank(owner1);
        c.owned();

        // Now call owned() from owner2 (should fail because onlyOwner, but let's check)
        // Actually we need to make owner2 the owner first to call burn
        // Strategy: set owner to owner1, then call owned() from owner2? No, owned() requires msg.sender == owner.
        // Alternative: set owner to owner1, then have owner1 call owned()? That doesn't change owner.
        // Let's think: we need burn to change owner in reference but not in buggy.
        // Reference: owned() sets owner = msg.sender. After burn, owned() is called? No, burn doesn't call owned().
        // Wait: the difference says after burn(), owner differs. But burn() doesn't call owned().
        // The mutant changes owned() body, but how does burn() affect owner?
        // Actually, looking at the code, burn() does not call owned(). The only way owner changes is via owned().
        // So the difference must be: in reference, after some call sequence ending with burn, owner is different.
        // But burn() alone doesn't change owner. So maybe the intended scenario is:
        // - Call owned() from account A (sets owner = A)
        // - Then call burn() from account B (but onlyOwner will fail because B is not owner)
        // Hmm.
        // Let's re-read: "after a call to burn(...) completes, the value of state variable owner differs: P.owner() != M.owner()"
        // That means the bug affects something that makes burn change owner indirectly? Or the test sequence includes owned() before burn?
        // Maybe the scenario: first call owned() from account X (sets owner to X in reference, does nothing in buggy because buggy owned() does nothing).
        // Then call burn() from some account that becomes owner in reference but not in buggy? No.
        // Let's try: set initial owner = address(this) via constructor? Constructor sets owner = msg.sender (which is address(this) in setUp).
        // Then: vm.prank(address(1)); c.owned(); // In reference: owner becomes address(1). In buggy: owner stays address(this).
        // Then: c.burn(0); // This works because msg.sender is address(this) which is owner in buggy but not in reference.
        // So in reference, burn reverts because msg.sender is not owner. In buggy, burn succeeds.
        // That's a revert difference. Let's do that.

        vm.prank(address(1));
        c.owned();

        // Now try to burn from address(this)
        bool ok = false;
        try c.burn(0) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: burn reverts (owner is address(1)), so ok = false.
        // Buggy: burn succeeds (owner is still address(this)), so ok = true.
        assertTrue(ok); 
    }
}

