pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testRegression_property() public {
        // Set up non-owner caller
        address nonOwner = address(0x1234);

        // Mint some tokens to nonOwner so they have balance to burn
        c.mintToken(nonOwner, 100);

        // Record original owner (deployer = address(this))
        address originalOwner = c.owner();

        // nonOwner calls burn, which triggers onlyOwner check
        // In reference: reverts because onlyOwner fails => owner unchanged
        // In buggy: passes, calls burn, but burn only reduces balance, doesn't change owner
        // However, buggy onlyOwner lets nonOwner call owned() inside? No, owned() is separate.
        // Actually, the mutation allows nonOwner to call owned() which changes owner.
        // So we need nonOwner to call owned() first, then burn:
        vm.prank(nonOwner);
        c.owned();  // In buggy, this succeeds and sets owner = nonOwner

        // Now nonOwner calls burn
        vm.prank(nonOwner);
        c.burn(1);

        // Assert: owner changed? In reference, owned() reverts (onlyOwner fails), so owner stays original.
        // In buggy, owned() succeeds, so owner becomes nonOwner.
        assertTrue(c.owner() == originalOwner);
    }
}

