pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(100, "T", "T"); }
    function testRegression_property() public {
        // Set up: owner is the test contract
        address owner = address(this);
        // Call owned() to set owner (in reference, remains msg.sender; in bug, becomes address(this))
        // The test contract is currently the owner
        c.owned();
        // Now burn 100 tokens
        c.burn(100);
        // In the reference, owner is this address; in the bug, owner is address(this) which equals this address because this test deploys the contract
        // Actually both will have owner = address(this) because the test contract is both caller and the contract itself? Let's adjust.
        // We need to call from a different address to trigger the difference.
        // Redo: use vm.prank to call owned() from a different address that is initially owner? No.
        // Simpler: The test contract is the deployer, so owner = address(this). Call owned() from the test contract: reference sets owner = msg.sender = address(this). Bug sets owner = address(this) (the contract). Both are the same because address(this) is the test contract. That won't diverge.
        // To diverge, we need to have a different caller for owned(). But onlyOwner restriction: msg.sender must be owner. We can set up by transferring ownership? No, only owned() changes owner. Initially owner = deployer = test contract. So we can only call owned() as test contract. That yields same owner in both. So we need to use a different entry point? The hint says driven through burn, and the difference is owner differs after burn. The mutant only changes owned(). So we must call owned() first (as owner) to change owner to address(this) in bug vs msg.sender in reference. Then after burn, owner differs. But if we call owned() as owner (test contract), in reference owner = test contract; in bug owner = contract address. Those are different (contract address != test contract address). So it works: reference owner = address(this) (test contract), bug owner = address(c) (contract). So we can assert that owner equals the test contract in reference, but not in bug.
        vm.prank(owner);
        c.owned();
        c.burn(100);
        address expectedOwner = address(this); // reference sets owner to msg.sender
        assertTrue(c.owner() == expectedOwner, "Owner should be the caller");
    }
}

