import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testRegression_property() public {
        address owner = address(this);
        address nonOwner = address(0xBEEF);
        vm.deal(nonOwner, 1 ether);
        // Owner mints 1 token to themselves
        c.mintToken(owner, 1);
        // Owner mints 1 token to nonOwner
        c.mintToken(nonOwner, 1);
        // nonOwner tries to burn 1 token
        vm.prank(nonOwner);
        try c.burn(1) {
            // Buggy version: burn succeeds
        } catch {
            // Reference version: reverts due to onlyOwner
        }
        // After the call, reference leaves nonOwner's balance unchanged (1), buggy reduces it to 0
        assertTrue(c.balanceOf(nonOwner) < 1);
    }
}

